// Build only from the Go service's local static fixture; the independent wire
// fixture can exercise the same contract once generated by integration.
func orcaAdaptiveTestPool(t *testing.T, mutate func(map[string]any)) Pool {
	t.Helper()
	p := orcaTestPool(t)
	p.Protocol = "orca-whirlpools-adaptive"
	p.AdapterVersion = "orca-whirlpools/cc683ec9-spl-adaptive-1"
	s := p.OrcaWhirlpool
	s.FeeTierIndex = 128
	s.RewardInfos = make([]OrcaRewardInfo, 3)
	for i := range s.RewardInfos {
		s.RewardInfos[i] = OrcaRewardInfo{Mint: "11111111111111111111111111111111", Vault: "11111111111111111111111111111111", Extension: make([]uint32, 32), EmissionsPerSecondX64: "0", GrowthGlobalX64: "0"}
	}
	s.RewardInfos[0].Extension[0] = 255
	for i := range s.TickArrays {
		for j := range s.TickArrays[i].Ticks {
			s.TickArrays[i].Ticks[j].RewardGrowthsOutside = []Amount{"0", "0", "0"}
		}
	}
	pattern := func(n int) []uint32 {
		b := make([]uint32, n)
		for i := range b {
			b[i] = uint32((i*17 + 255) % 256)
		}
		return b
	}
	adaptive := map[string]any{
		"whirlpool": p.PoolID, "trade_enable_timestamp": s.BankUnixTimestamp,
		"filter_period": uint32(10), "decay_period": uint32(120), "reduction_factor": uint32(5000),
		"adaptive_fee_control_factor": uint32(1000), "max_volatility_accumulator": uint32(1000000),
		"tick_group_size": uint32(8), "major_swap_threshold_ticks": uint32(64), "constants_reserved": pattern(16),
		"last_reference_update_timestamp": s.BankUnixTimestamp - 10, "last_major_swap_timestamp": s.BankUnixTimestamp,
		"volatility_reference": uint32(10000), "tick_group_index_reference": int32(-1),
		"volatility_accumulator": uint32(20000), "variables_reserved": pattern(16), "reserved": pattern(128),
	}
	if mutate != nil {
		mutate(adaptive)
	}
	raw, err := json.Marshal(s)
	if err != nil {
		t.Fatal(err)
	}
	var state map[string]json.RawMessage
	if err = json.Unmarshal(raw, &state); err != nil {
		t.Fatal(err)
	}
	state["adaptive"], err = json.Marshal(adaptive)
	if err != nil {
		t.Fatal(err)
	}
	raw, err = json.Marshal(state)
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(raw, s); err != nil {
		t.Fatal(err)
	}
	return p
}

func TestOrcaAdaptiveProfileAndState(t *testing.T) {
	profile, ok := Protocol("orca-whirlpools-adaptive")
	if !ok || profile.Family != "orca" || profile.AdapterVersion != "orca-whirlpools/cc683ec9-spl-adaptive-1" || profile.FeeDenominator != 1000000 || !profile.RequireIdentity {
		t.Fatal("missing independent adaptive profile", profile)
	}
	p := orcaAdaptiveTestPool(t, nil)
	if err := p.OrcaWhirlpool.Validate(p); err != nil {
		t.Fatal(err)
	}
}

func TestOrcaAdaptiveJSONAndProtoPreserveFullState(t *testing.T) {
	p := orcaAdaptiveTestPool(t, nil)
	w, err := OrcaWhirlpoolToProto(p.OrcaWhirlpool)
	if err != nil {
		t.Fatal(err)
	}
	if w.Adaptive == nil {
		t.Fatal("adaptive payload lost")
	}
	if w.ProtoReflect().Descriptor().Fields().ByName("adaptive").Number() != 51 {
		t.Fatal("adaptive field must be 51")
	}
	for field := 32; field <= 49; field++ {
		if !w.ProtoReflect().Descriptor().ReservedRanges().Has(protoreflect.FieldNumber(field)) {
			t.Fatalf("legacy field %d must remain reserved", field)
		}
	}
	encoded, err := proto.Marshal(w)
	if err != nil {
		t.Fatal(err)
	}
	decoded := new(pb.OrcaWhirlpoolState)
	if err = proto.Unmarshal(encoded, decoded); err != nil {
		t.Fatal(err)
	}
	state, err := OrcaWhirlpoolFromProto(decoded)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(state, p.OrcaWhirlpool) {
		t.Fatal("JSON/protobuf round trip changed state")
	}
	// Conversions must own their byte slices, in both directions.
	before, _ := Hash(state)
	decoded.Adaptive.ConstantsReserved[0] ^= 1
	decoded.Adaptive.VariablesReserved[0] ^= 1
	decoded.Adaptive.Reserved[0] ^= 1
	decoded.RewardInfos[0].Extension[0] ^= 1
	after, _ := Hash(state)
	if before != after {
		t.Fatal("decoded state aliases protobuf bytes")
	}
}

func TestOrcaAdaptiveInvalidPayload(t *testing.T) {
	cases := map[string]func(map[string]any){
		"bad-key":              func(a map[string]any) { a["whirlpool"] = "not-base58" },
		"trade-future":         func(a map[string]any) { a["trade_enable_timestamp"] = uint64(math.MaxUint64) },
		"reference-future":     func(a map[string]any) { a["last_reference_update_timestamp"] = uint64(math.MaxUint64) },
		"major-future":         func(a map[string]any) { a["last_major_swap_timestamp"] = uint64(math.MaxUint64) },
		"filter-zero":          func(a map[string]any) { a["filter_period"] = 0 },
		"filter-wide":          func(a map[string]any) { a["filter_period"] = 65536; a["decay_period"] = 65537 },
		"decay-wide":           func(a map[string]any) { a["decay_period"] = 65536 },
		"decay-equal":          func(a map[string]any) { a["decay_period"] = 10 },
		"decay-before-filter":  func(a map[string]any) { a["decay_period"] = 9 },
		"reduction-limit":      func(a map[string]any) { a["reduction_factor"] = 10000 },
		"control-limit":        func(a map[string]any) { a["adaptive_fee_control_factor"] = 100000 },
		"product-overflow":     func(a map[string]any) { a["max_volatility_accumulator"] = uint32(math.MaxUint32/8 + 1) },
		"group-zero":           func(a map[string]any) { a["tick_group_size"] = 0 },
		"group-nondivisor":     func(a map[string]any) { a["tick_group_size"] = 3 },
		"group-over-spacing":   func(a map[string]any) { a["tick_group_size"] = 128 },
		"group-wide":           func(a map[string]any) { a["tick_group_size"] = 65536 },
		"major-zero":           func(a map[string]any) { a["major_swap_threshold_ticks"] = 0 },
		"major-over-array":     func(a map[string]any) { a["major_swap_threshold_ticks"] = 64*88 + 1 },
		"major-wide":           func(a map[string]any) { a["major_swap_threshold_ticks"] = 65536 },
		"reference-over-max":   func(a map[string]any) { a["volatility_reference"] = 1000001 },
		"accumulator-over-max": func(a map[string]any) { a["volatility_accumulator"] = 1000001 },
		"group-reference-min":  func(a map[string]any) { a["tick_group_index_reference"] = -55456 },
		"group-reference-max":  func(a map[string]any) { a["tick_group_index_reference"] = 55455 },
	}
	for _, field := range []string{"constants_reserved", "variables_reserved", "reserved"} {
		size := 16
		if field == "reserved" {
			size = 128
		}
		for _, n := range []int{0, size - 1, size + 1} {
			cases[field+"-length-"+strconv.Itoa(n)] = func(a map[string]any) { a[field] = make([]uint32, n) }
		}
		cases[field+"-byte-overflow"] = func(a map[string]any) { b := make([]uint32, size); b[size-1] = 256; a[field] = b }
		cases[field+"-missing"] = func(a map[string]any) { delete(a, field) }
	}
	for name, mutate := range cases {
		t.Run(name, func(t *testing.T) {
			p := orcaAdaptiveTestPool(t, mutate)
			if p.OrcaWhirlpool.Validate(p) == nil {
				t.Fatal("invalid adaptive accepted")
			}
			if _, err := OrcaWhirlpoolToProto(p.OrcaWhirlpool); err == nil {
				t.Fatal("invalid adaptive narrowed on encode")
			}
		})
	}
}

func TestOrcaAdaptiveRejectsProtocolAndStateMixing(t *testing.T) {
	cases := map[string]func(*Pool){
		"static-profile": func(p *Pool) {
			p.Protocol = "orca-whirlpools-static"
			p.AdapterVersion = "orca-whirlpools/cc683ec9-spl-static-1"
		},
		"rewards-profile": func(p *Pool) {
			p.Protocol = "orca-whirlpools-rewards"
			p.AdapterVersion = "orca-whirlpools/cc683ec9-spl-rewards-1"
		},
		"wrong-adapter":      func(p *Pool) { p.AdapterVersion = "orca-whirlpools/cc683ec9-spl-rewards-1" },
		"tier-equal-spacing": func(p *Pool) { p.OrcaWhirlpool.FeeTierIndex = p.OrcaWhirlpool.TickSpacing },
		"tier-wide":          func(p *Pool) { p.OrcaWhirlpool.FeeTierIndex = 65536 },
		"base-fee":           func(p *Pool) { p.OrcaWhirlpool.FeeRate = 60001; p.FeeNumerator = 60001 },
		"rewards-absent":     func(p *Pool) { p.OrcaWhirlpool.RewardInfos = nil },
		"reward-initialized": func(p *Pool) {
			p.OrcaWhirlpool.RewardInfos[0].Mint = p.Token0
			p.OrcaWhirlpool.RewardInfos[0].Vault = p.OrcaWhirlpool.Vault0
		},
		"slot1-control": func(p *Pool) { p.OrcaWhirlpool.RewardInfos[1].Extension[0] = 1 },
		"slot2-control": func(p *Pool) { p.OrcaWhirlpool.RewardInfos[2].Extension[31] = 1 },
		"dynamic-array": func(p *Pool) { p.OrcaWhirlpool.TickArrays[1].Layout = "dynamic" },
		"two-arrays":    func(p *Pool) { p.OrcaWhirlpool.TickArrays = p.OrcaWhirlpool.TickArrays[:2] },
		"four-arrays": func(p *Pool) {
			a := p.OrcaWhirlpool.TickArrays[2]
			a.Address = p.Token1
			a.StartTickIndex += int32(88 * p.OrcaWhirlpool.TickSpacing)
			a.Ticks = nil
			a.InitializedBitmap = "0"
			p.OrcaWhirlpool.TickArrays = append(p.OrcaWhirlpool.TickArrays, a)
		},
	}
	for name, mutate := range cases {
		t.Run(name, func(t *testing.T) {
			p := orcaAdaptiveTestPool(t, nil)
			mutate(&p)
			if p.OrcaWhirlpool.Validate(p) == nil {
				t.Fatal("mixed adaptive accepted")
			}
		})
	}
	p := orcaAdaptiveTestPool(t, func(a map[string]any) { a["whirlpool"] = OrcaProgram })
	if p.OrcaWhirlpool.Validate(p) == nil {
		t.Fatal("foreign whirlpool accepted")
	}
}

func TestOrcaAdaptivePoolEntryAndClone(t *testing.T) {
	p := orcaAdaptiveTestPool(t, nil)
	if err := p.Validate(); err != nil {
		t.Fatal(err)
	}
	before, _ := Hash(p)
	copy := p.Clone()
	if !reflect.DeepEqual(copy, p) {
		t.Fatal("clone changed state")
	}
	copy.OrcaWhirlpool.Adaptive.ConstantsReserved[0] ^= 1
	copy.OrcaWhirlpool.Adaptive.VariablesReserved[0] ^= 1
	copy.OrcaWhirlpool.Adaptive.Reserved[127] ^= 1
	copy.OrcaWhirlpool.Adaptive.VolatilityAccumulator++
	copy.OrcaWhirlpool.RewardInfos[0].Extension[0] ^= 1
	copy.OrcaWhirlpool.TickArrays[1].Ticks[0].RewardGrowthsOutside[0] = "1"
	copy.OrcaWhirlpool.TickArrays[1].Ticks[0].LiquidityNet = "0"
	copy.OrcaWhirlpool.TickArrays[0].Layout = "dynamic"
	after, _ := Hash(p)
	if before != after {
		t.Fatal("clone aliases adaptive, reserved, rewards or tick state")
	}
	for name, mutate := range map[string]func(*Pool){
		"missing-adaptive": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive = nil
			p.OrcaWhirlpool.FeeTierIndex = p.OrcaWhirlpool.TickSpacing
		},
		"missing-state":     func(p *Pool) { p.OrcaWhirlpool = nil },
		"foreign-protocol":  func(p *Pool) { p.Protocol = "fixture-cpmm" },
		"mixed-model":       func(p *Pool) { p.V3 = new(V3State) },
		"foreign-whirlpool": func(p *Pool) { p.OrcaWhirlpool.Adaptive.Whirlpool = p.Token0 },
	} {
		t.Run(name, func(t *testing.T) {
			p := orcaAdaptiveTestPool(t, nil)
			mutate(&p)
			if p.Validate() == nil {
				t.Fatal("invalid adaptive pool accepted")
			}
		})
	}
}

func TestOrcaAdaptiveNativeBoundaryValues(t *testing.T) {
	for name, mutate := range map[string]func(*Pool){
		"tier-zero":    func(p *Pool) { p.OrcaWhirlpool.FeeTierIndex = 0 },
		"tier-u16-max": func(p *Pool) { p.OrcaWhirlpool.FeeTierIndex = math.MaxUint16 },
		"base-fee-max": func(p *Pool) { p.OrcaWhirlpool.FeeRate = 60000; p.FeeNumerator = 60000 },
		"period-u16-max": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.FilterPeriod = 65534
			p.OrcaWhirlpool.Adaptive.DecayPeriod = 65535
		},
		"factors-max": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.ReductionFactor = 9999
			p.OrcaWhirlpool.Adaptive.AdaptiveFeeControlFactor = 99999
		},
		"zero-control": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.ReductionFactor = 0
			p.OrcaWhirlpool.Adaptive.AdaptiveFeeControlFactor = 0
		},
		"max-product": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.MaxVolatilityAccumulator = math.MaxUint32 / 8
			p.OrcaWhirlpool.Adaptive.VolatilityReference = math.MaxUint32 / 8
			p.OrcaWhirlpool.Adaptive.VolatilityAccumulator = math.MaxUint32 / 8
		},
		"zero-accumulator": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.MaxVolatilityAccumulator = 0
			p.OrcaWhirlpool.Adaptive.VolatilityReference = 0
			p.OrcaWhirlpool.Adaptive.VolatilityAccumulator = 0
		},
		"group-equal-spacing": func(p *Pool) { p.OrcaWhirlpool.Adaptive.TickGroupSize = p.OrcaWhirlpool.TickSpacing },
		"major-array-limit":   func(p *Pool) { p.OrcaWhirlpool.Adaptive.MajorSwapThresholdTicks = p.OrcaWhirlpool.TickSpacing * 88 },
		"timestamps-zero": func(p *Pool) {
			p.OrcaWhirlpool.Adaptive.TradeEnableTimestamp = 0
			p.OrcaWhirlpool.Adaptive.LastReferenceUpdateTimestamp = 0
			p.OrcaWhirlpool.Adaptive.LastMajorSwapTimestamp = 0
		},
	} {
		t.Run(name, func(t *testing.T) {
			p := orcaAdaptiveTestPool(t, nil)
			mutate(&p)
			if err := p.Validate(); err != nil {
				t.Fatal(err)
			}
			w, err := OrcaWhirlpoolToProto(p.OrcaWhirlpool)
			if err != nil {
				t.Fatal(err)
			}
			if _, err = OrcaWhirlpoolFromProto(w); err != nil {
				t.Fatal(err)
			}
		})
	}
	for _, size := range []int32{1, 4, 8, 64} {
		min := (OrcaMinTick - 1) / size
		if (OrcaMinTick-1)%size != 0 {
			min--
		}
		max := OrcaMaxTick / size
		for _, ref := range []int32{min - 1, min, max, max + 1} {
			p := orcaAdaptiveTestPool(t, nil)
			p.OrcaWhirlpool.Adaptive.TickGroupSize = uint32(size)
			p.OrcaWhirlpool.Adaptive.TickGroupIndexReference = ref
			err := p.Validate()
			valid := ref >= min && ref <= max
			if (err == nil) != valid {
				t.Fatalf("group=%d reference=%d valid=%v error=%v", size, ref, valid, err)
			}
		}
	}
}

func TestOrcaAdaptiveFromProtoValidatesBeforeNarrowing(t *testing.T) {
	p := orcaAdaptiveTestPool(t, nil)
	base, err := OrcaWhirlpoolToProto(p.OrcaWhirlpool)
	if err != nil {
		t.Fatal(err)
	}
	for name, mutate := range map[string]func(*pb.OrcaWhirlpoolState){
		"period-u16":        func(s *pb.OrcaWhirlpoolState) { s.Adaptive.DecayPeriod = 65536 },
		"filter-u16":        func(s *pb.OrcaWhirlpoolState) { s.Adaptive.FilterPeriod = 65536; s.Adaptive.DecayPeriod = 65537 },
		"major-u16":         func(s *pb.OrcaWhirlpoolState) { s.Adaptive.MajorSwapThresholdTicks = 65536 },
		"group-u16":         func(s *pb.OrcaWhirlpoolState) { s.Adaptive.TickGroupSize = 65536 },
		"fee-tier-u16":      func(s *pb.OrcaWhirlpoolState) { s.FeeTierIndex = 65536 },
		"constants-width":   func(s *pb.OrcaWhirlpoolState) { s.Adaptive.ConstantsReserved = s.Adaptive.ConstantsReserved[:15] },
		"variables-width":   func(s *pb.OrcaWhirlpoolState) { s.Adaptive.VariablesReserved = nil },
		"reserved-width":    func(s *pb.OrcaWhirlpoolState) { s.Adaptive.Reserved = append(s.Adaptive.Reserved, 0) },
		"future-trade":      func(s *pb.OrcaWhirlpoolState) { s.Adaptive.TradeEnableTimestamp = s.BankUnixTimestamp + 1 },
		"future-reference":  func(s *pb.OrcaWhirlpoolState) { s.Adaptive.LastReferenceUpdateTimestamp = s.BankUnixTimestamp + 1 },
		"future-major":      func(s *pb.OrcaWhirlpoolState) { s.Adaptive.LastMajorSwapTimestamp = s.BankUnixTimestamp + 1 },
		"invalid-reference": func(s *pb.OrcaWhirlpoolState) { s.Adaptive.TickGroupIndexReference = math.MinInt32 },
		"product-overflow":  func(s *pb.OrcaWhirlpoolState) { s.Adaptive.MaxVolatilityAccumulator = math.MaxUint32 },
		"over-max-vars": func(s *pb.OrcaWhirlpoolState) {
			s.Adaptive.VolatilityAccumulator = s.Adaptive.MaxVolatilityAccumulator + 1
		},
		"missing-reward": func(s *pb.OrcaWhirlpoolState) { s.RewardInfos[1] = nil },
		"dynamic-array":  func(s *pb.OrcaWhirlpoolState) { s.TickArrays[1].Layout = "dynamic" },
	} {
		t.Run(name, func(t *testing.T) {
			w := proto.Clone(base).(*pb.OrcaWhirlpoolState)
			mutate(w)
			if name == "dynamic-array" {
				state, err := OrcaWhirlpoolFromProto(w)
				if err != nil {
					t.Fatal("generic wire must preserve dynamic layout", err)
				}
				pool := p
				pool.OrcaWhirlpool = state
				if pool.Validate() == nil {
					t.Fatal("old adaptive profile accepted dynamic array")
				}
				return
			}
			if _, err := OrcaWhirlpoolFromProto(w); err == nil {
				t.Fatal("invalid adaptive protobuf accepted")
			}
		})
	}
}

func TestOrcaAdaptiveJSONRejectsNativeOverflow(t *testing.T) {
	for name, value := range map[string]string{"filter_period": "4294967296", "tick_group_index_reference": "2147483648", "trade_enable_timestamp": "-1", "constants_reserved": "[-1]", "variables_reserved": "[4294967296]"} {
		t.Run(name, func(t *testing.T) {
			var s OrcaAdaptiveState
			if json.Unmarshal([]byte(`{"`+name+`":`+value+`}`), &s) == nil {
				t.Fatal("JSON native integer overflow accepted")
			}
		})
	}
}
